// Game data from web/assets/data (generated by tools/extract_data.js from the decomp)
// plus the Gen 3 formulas we keep (stats, EXP curves, type chart, damage).

export const D = {
  species: {}, moves: {}, types: { list: [], chart: {} }, items: {}, trainers: {},
  encounters: {}, maps: {}, trainerClasses: {},
};

const FILES = {
  species: 'species.json', moves: 'moves.json', types: 'types.json', items: 'items.json',
  trainers: 'trainers.json', encounters: 'encounters.json', maps: 'maps.json', trainerClasses: 'trainer_classes.json',
};

export async function loadData(loader) {
  await Promise.all(Object.entries(FILES).map(async ([k, f]) => {
    try { D[k] = await loader(f); } catch (e) { console.warn('data load failed', f, e); }
  }));
  for (const [key, s] of Object.entries(D.species)) { s.key = key; if (s.dex) byDex[s.dex] = s; }
  for (const [key, m] of Object.entries(D.moves)) m.key = key;
  for (const [key, it] of Object.entries(D.items)) it.key = key;
  for (const [key, t] of Object.entries(D.trainers)) t.key = key;
  return D;
}
export const byDex = [];

// Gen 3: the move's type decides physical vs special.
export const SPECIAL_TYPES = new Set(['FIRE', 'WATER', 'GRASS', 'ELECTRIC', 'PSYCHIC', 'ICE', 'DRAGON', 'DARK']);
export const isSpecial = type => SPECIAL_TYPES.has(type);

export const TYPE_COLORS = {
  NORMAL: '#a8a878', FIGHTING: '#c03028', FLYING: '#a890f0', POISON: '#a040a0', GROUND: '#e0c068',
  ROCK: '#b8a038', BUG: '#a8b820', GHOST: '#705898', STEEL: '#b8b8d0', FIRE: '#f08030',
  WATER: '#6890f0', GRASS: '#78c850', ELECTRIC: '#f8d030', PSYCHIC: '#f85888', ICE: '#98d8d8',
  DRAGON: '#7038f8', DARK: '#705848', MYSTERY: '#68a090',
};

export function typeEffect(atkType, defTypes) {
  let m = 1;
  const row = D.types.chart[atkType] || {};
  for (const t of defTypes) if (row[t] !== undefined) m *= row[t];
  return m;
}

export function calcStat(base, iv, level, isHP) {
  const core = Math.floor(((2 * base + iv) * level) / 100);
  return isHP ? core + level + 10 : core + 5;
}

export function monStats(speciesKey, level, iv = 15) {
  const b = D.species[speciesKey].stats;
  return {
    hp: calcStat(b.hp, iv, level, true), atk: calcStat(b.atk, iv, level), def: calcStat(b.def, iv, level),
    spa: calcStat(b.spa, iv, level), spd: calcStat(b.spd, iv, level), spe: calcStat(b.spe, iv, level),
  };
}

export function expForLevel(rate, n) {
  if (n <= 1) return 0;
  const n3 = n * n * n;
  switch (rate) {
    case 'FAST': return Math.floor((4 * n3) / 5);
    case 'MEDIUM_SLOW': return Math.max(0, Math.floor((6 * n3) / 5 - 15 * n * n + 100 * n - 140));
    case 'SLOW': return Math.floor((5 * n3) / 4);
    case 'ERRATIC':
      if (n <= 50) return Math.floor((n3 * (100 - n)) / 50);
      if (n <= 68) return Math.floor((n3 * (150 - n)) / 100);
      if (n <= 98) return Math.floor((n3 * Math.floor((1911 - 10 * n) / 3)) / 500);
      return Math.floor((n3 * (160 - n)) / 100);
    case 'FLUCTUATING':
      if (n <= 15) return Math.floor((n3 * (Math.floor((n + 1) / 3) + 24)) / 50);
      if (n <= 36) return Math.floor((n3 * (n + 14)) / 50);
      return Math.floor((n3 * (Math.floor(n / 2) + 32)) / 50);
    default: return n3;
  }
}

// Last 4 distinct moves learned at or below `level` (what wild mons know in the games).
export function defaultMoves(speciesKey, level) {
  const known = [];
  for (const [lvl, mv] of D.species[speciesKey]?.learnset || []) {
    if (lvl > level) break;
    if (!D.moves[mv]) continue;
    const i = known.indexOf(mv);
    if (i >= 0) known.splice(i, 1);
    known.push(mv);
  }
  return known.length ? known.slice(-4) : ['TACKLE'];
}

export function movesLearnedAt(speciesKey, level) {
  return (D.species[speciesKey]?.learnset || []).filter(([l, m]) => l === level && D.moves[m]).map(([, m]) => m);
}

// Level-up evolution target (plus the Atk/Def Hitmon and Wurmple style splits), or null.
export function levelEvolution(speciesKey, level, stats) {
  for (const e of D.species[speciesKey]?.evolutions || []) {
    if (e.method === 'LEVEL' && level >= e.param) return e.into;
    if (e.method === 'LEVEL_ATK_GT_DEF' && level >= e.param && stats && stats.atk > stats.def) return e.into;
    if (e.method === 'LEVEL_ATK_LT_DEF' && level >= e.param && stats && stats.atk < stats.def) return e.into;
    if (e.method === 'LEVEL_ATK_EQ_DEF' && level >= e.param && stats && stats.atk === stats.def) return e.into;
  }
  return null;
}
export function stoneEvolution(speciesKey, item) {
  return (D.species[speciesKey]?.evolutions || []).find(e => e.method === 'ITEM' && e.param === item)?.into || null;
}
// Friendship/trade evolutions happen at a fixed level in this game so every line can finish evolving.
export function easyEvolution(speciesKey, level) {
  for (const e of D.species[speciesKey]?.evolutions || []) {
    if ((e.method === 'FRIENDSHIP' || e.method === 'TRADE' || e.method === 'TRADE_ITEM' || e.method === 'FRIENDSHIP_DAY' || e.method === 'FRIENDSHIP_NIGHT') && level >= 30) return e.into;
  }
  return null;
}

export const displayName = key => D.species[key]?.name || key;
export const moveName = key => D.moves[key]?.name || key;
